import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.CvYJ3hxD.js";const m=JSON.parse('{"title":"Unified Filters — the integration seam","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/unified-filters-seam.md","filePath":"integrations/unified-filters-seam.md","lastUpdated":1789374597000}'),l={name:"integrations/unified-filters-seam.md"};function r(d,s,n,o,p,c){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="unified-filters-—-the-integration-seam" tabindex="-1">Unified Filters — the integration seam <a class="header-anchor" href="#unified-filters-—-the-integration-seam" aria-label="Permalink to &quot;Unified Filters — the integration seam&quot;">​</a></h1><p>What a feature team authors — plus the provided defaults it can override.</p><p class="seam-hint">Hover an item on the left to see its detail on the right.</p><div class="seam-layout"><div class="seam-checklist"><div class="seam-heading">You author</div><div class="chk"><span class="tick">✓</span> FiltersScope</div><div class="chk"><span class="tick">✓</span> FilterQueryParameters</div><div class="chk"><span class="tick">✓</span> FiltersDisplayNamesResolver</div><div class="chk"><span class="tick">✓</span> The two Mappers</div><div class="chk"><span class="tick">✓</span> Drilldown options providers</div><div class="chk"><span class="tick">✓</span> QuickFiltersProvider <span class="opt">(optional)</span></div><div class="chk"><span class="tick">✓</span> FiltersModelHolderFactory</div><div class="seam-heading">Provided — override when…</div><div class="chk"><span class="dtick"></span> DomainFiltersModelStore</div><div class="chk"><span class="dtick"></span> FiltersModelProvider</div><div class="chk"><span class="dtick"></span> DomainFiltersModelUpdater</div></div><div class="seam-divider"></div><div class="spot-area"><div class="spot-item"><span class="sn">FiltersScope</span><div class="sd">The key for one filterable surface (a log, a picker) — a sealed class in PGF. It keys both the persisted selection and analytics; the framework resolves everything else from it.</div></div><div class="spot-item"><span class="sn">FilterQueryParameters</span><div class="sd">The <code>@Serializable</code> persisted shape. Holds ids — never display names — so filter options survive being renamed. This is what actually gets stored.</div></div><div class="spot-item"><span class="sn">FiltersDisplayNamesResolver</span><div class="sd">Turns persisted ids back into display names (Text, Members, Hierarchy type of filters) at read time. Shared across platforms — it&#39;s why FilterQueryParameters can stay ids-only.</div></div><div class="spot-item"><span class="sn">The two Mappers</span><div class="sd">Two translation seams:<ul class="spotlist"><li><b>DomainFiltersModelMapper</b> — your model ↔ the panel&#39;s UI shape.</li><li><b>FilterQueryParametersMapper</b> — your model ↔ the persisted shape.</li></ul></div></div><div class="spot-item"><span class="sn">Drilldown options providers</span><div class="sd">Feed the option lists behind <em>every</em> filter drilldown — statuses, types, members, locations, custom fields, and whatever else your domain filters by. One provider per filter.</div></div><div class="spot-item"><span class="sn">QuickFiltersProvider <span class="opt">(optional)</span></span><div class="sd">Supplies the preset chips, applied atomically. The out-of-the-box set is <em>Assigned to Me · My Company · Due in 7 Days</em>.<span style="display:block;margin-top:0.35em;">Skip it if your domain doesn&#39;t need Quick Filters chips — the Filters Panel works on its own.</span></div></div><div class="spot-item"><span class="sn">FiltersModelHolderFactory</span><div class="sd">The final wiring — assembles the read-side <b>FiltersModelProvider</b> and the write-side <b>Updater</b> into the <b>FiltersModelHolder</b> (the filters presentation state machine). One holder per scope.</div></div><div class="spot-item"><span class="sn">DomainFiltersModelStore</span><div class="sd"><div>The top of the persistence stack — exposes <code>currentFilter</code> (observed by filters presentations and feature teams&#39; list), persists every change, and holds the <b>default filter</b> applied when nothing is stored yet, and on reset.</div><div style="margin-top:0.5rem;"><span class="plabel">Default</span> — the generic impl derives your model straight from the persisted params.</div><div style="margin-top:0.5rem;"><span class="plabel">Override when</span> — your model blends other reactive sources (dynamic types, custom attributes).</div></div></div><div class="spot-item"><span class="sn">FiltersModelProvider</span><div class="sd"><div><span class="plabel">Default</span> — reads the store, maps to the UI shape, merges resolved display names.</div><div style="margin-top:0.5rem;"><span class="plabel">Override when</span> — options are dynamically available (derive the lists from the live filtered data).</div></div></div><div class="spot-item"><span class="sn">DomainFiltersModelUpdater</span><div class="sd"><div><span class="plabel">Default</span> — writes the filters presentation&#39;s edits straight back to the store.</div><div style="margin-top:0.5rem;"><span class="plabel">Override when</span> — you must preserve non-filter fields (sort, search, template) or make filters depend on each other.</div></div></div></div></div>',4)])])}const h=e(l,[["render",r]]);export{m as __pageData,h as default};
